#!/usr/bin/env python3
"""apply_distress_prereg.py -- canonical distress genome + debt seeding + prereg.

Run from the primordial repo root:  python3.10 apply_distress_prereg.py
Idempotent; refuses to overwrite files whose content differs."""
import os, sys

def put(path, content, label):
    if os.path.exists(path):
        if open(path).read() == content:
            print(f"  = {label}: already present"); return
        sys.exit(f"{path} exists with DIFFERENT content -- refusing to overwrite.")
    open(path, "w").write(content); print(f"  + {label}")

if not os.path.exists("genomes/distress_vol_sp400.json"):
    sys.exit("run from the primordial repo root (genomes/ not found).")

put("genomes/distress_base.json", "{\"timeframe\": \"1d\", \"root_type\": \"bool\", \"entry_tree\": {\"op\": \"and\", \"ch\": [{\"op\": \"gt\", \"ch\": [{\"op\": \"pctile_rank\", \"ch\": [{\"op\": \"term\", \"ch\": [], \"name\": \"atr_pct\"}], \"n\": 252}, {\"op\": \"const\", \"ch\": [], \"value\": 0.9}]}, {\"op\": \"lt\", \"ch\": [{\"op\": \"term\", \"ch\": [], \"name\": \"close\"}, {\"op\": \"roll_mean\", \"ch\": [{\"op\": \"term\", \"ch\": [], \"name\": \"close\"}], \"n\": 200}]}]}, \"regime_tree\": null, \"direction\": \"long\", \"entry_style\": \"market\", \"entry_param\": 1, \"stop_atr\": 99.0, \"target_r\": 0.0, \"time_stop\": 0, \"trail_mode\": \"none\", \"max_hold\": 40, \"anchor_ema\": 26}", "genomes/distress_base.json (canonical, sha b62a9753323f1e5e)")
put("scripts/seed_ledger_distress.py", "\"\"\"\nSeed a manifest's ledger with the DISTRESS family's cross-universe debt.\n\nThe 2026-08-10 distress campaign tried 5 hand variants (base, stabilized,\nvolconf, deep, deep_short) across 14 validation runs on 10 universes\n(sp400 x1, sp600 x5, uk ca de jp kr tw au in x1 each). The selection event\nwas FAMILY-WIDE: the same idea kept being re-asked on fresh ground until\nsome ground said yes. A fingerprint that has only ever been asked once\nshows a 0.00 luck bar -- which is exactly how every international \"pass\"\nwas produced. Before believing any result on such ground, charge it the\nfamily's history:\n\n  python3.10 scripts/seed_ledger_distress.py --manifest manifests/jp_nikkei.yaml\n\nIdempotent: refuses to double-charge a fingerprint it already seeded.\n\"\"\"\nimport argparse\nimport os\nimport sys\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, ROOT)\n\nfrom primordial.judge import Ledger\nfrom primordial.pipeline import LEDGER_PATH\nfrom primordial.universe import Manifest\n\nNOTE = (\"distress family debt 2026-08-10: 5 hand variants, 14 holdout peeks \"\n        \"across 10 universes (sp400, sp600 x5, uk, ca, de, jp, kr, tw, au, \"\n        \"in). Family-wide selection; every ground this idea touches inherits \"\n        \"the full history or its bar is a lie.\")\n\nif __name__ == \"__main__\":\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"--manifest\", required=True)\n    ap.add_argument(\"--ledger\", default=LEDGER_PATH)\n    a = ap.parse_args()\n    mf = Manifest.load(a.manifest)\n    led = Ledger(a.ledger, mf.fingerprint())\n    if any(r.get(\"note\", \"\").startswith(\"distress family debt\")\n           for r in led._load().get(led.key, [])):\n        print(f\"fingerprint {mf.fingerprint()} already carries the distress \"\n              f\"debt -- nothing charged.\")\n        sys.exit(0)\n    before = led.effective_trials()\n    led.log(\"manual_research\", n_candidates=5, holdout_peeks=14, note=NOTE)\n    after = led.effective_trials()\n    print(f\"fingerprint {mf.fingerprint()}\")\n    print(f\"effective trials: {before} -> {after}   (ledger: {a.ledger})\")\n    print(\"luck bar on this ground now remembers the whole campaign.\")\n", "scripts/seed_ledger_distress.py")
put("DISTRESS_PREREG.md", "# DISTRESS pre-registration (draft -- unsigned until Blake edits and signs)\n\n## The record so far (all 2026-08-10, all PRE-v0.1.10 single-split draws)\n\nIdea family: buy 1d names in a high-vol regime (atr_pct 252d percentile\n> 0.9) trading BELOW their 200d mean; exit close > EMA26 or 40 days.\n5 variants tried; 14 holdout peeks across 10 universes in one evening.\n\nWhere real luck bars existed (US), the family lost:\n  sp400 base   +0.82 vs bar +0.87   FAIL\n  sp600 base   +0.45 vs bar +0.53   FAIL\n  sp600 stab   +0.35 vs bar +0.60   FAIL\n  sp600 volconf+0.51 vs bar +0.65   FAIL\n  sp600 deep   +0.92 vs bar +0.69   bootstrap 0.00 -> FAIL; rerun +0.31 vs\n                                    +0.73 (old fetch-order split bug)\nWhere bars read 0.00 (fresh fingerprints, effective trials = 1), it\n\"passed\": uk de jp kr tw au in. That geography pattern is NOT the idea\nworking abroad -- it is the location of unseeded ledgers. The bar was\nabsent, not beaten.\n\nExtra survivorship warning: this rule buys BELOW-trend high-vol names from\ncurrent-membership lists. Delisted names are exactly the ones it would\nhave bought. Positive results on current membership are close to\nuninformative; negative ones count.\n\n## Frozen spec\n\ngenomes/distress_base.json  (sha256 b62a9753323f1e5e)\n== the base rule only. The four mined variants (stabilized, volconf, deep,\ndeep_short) are CLOSED -- they exist as record in genomes/, not as\ncandidates. No new variants during evaluation.\n\n## Test sequence (stop at first FAIL)\n\nGATE A -- home ground, honest split\n  python3.10 scripts/validate_genome.py --manifest manifests/us_sp600.yaml \\\n      --genome genomes/distress_base.json --splits 5\n  PASS: median-across-splits SR > bar, and > bar on >= 4/5 splits.\n  FAIL -> the idea is DEAD. Do not proceed to Gate B. \"Maybe it only\n  works abroad\" is not a mechanism, it is where the unseeded ledgers were.\n\nGATE B -- two pre-named foreign grounds, debt charged first\n  python3.10 scripts/seed_ledger_distress.py --manifest manifests/jp_nikkei.yaml\n  python3.10 scripts/seed_ledger_distress.py --manifest manifests/uk_ftse250.yaml\n  then validate_genome --splits 5 on each.\n  PASS: on BOTH: median SR > seeded bar; breadth p < 0.01; bootstrap gate\n  passes on mechanism-scaled blocks. jp and uk are named NOW, before\n  results; no third country if one fails.\n\nGATE C -- point-in-time membership (only after A and B)\n  Re-test on one universe with real historical constituents including\n  delisted names (paid data: Norgate / Sharadar). This gate cannot be\n  waived for this rule shape; it is the gate the rule is most likely to\n  fail. No forward test, no deployment talk, before C.\n\n## Ledger accounting\n\nGate A charges 5 peeks to sp600 (already at 9+). Gate B charges the\nfamily debt (5 candidates, 14 peeks) plus 5 peeks per universe. That is\nthe cost of the evening of variant mining; it does not go away by\nswitching countries.\n\nSigned: ____________  date: __________\n(edit the thresholds if you disagree with them -- then sign. Unsigned,\nthis file is a proposal, not a registration.)\n", "DISTRESS_PREREG.md (draft -- read it, edit thresholds, sign)")

ADD = "\ndistress_base.json is THE distress rule (frozen; sha256 b62a9753323f1e5e). The\nsp400/sp600-suffixed distress_* files are the 2026-08-10 mined variants,\nkept as record and CLOSED as candidates. See DISTRESS_PREREG.md.\n"
r = open("genomes/README.md").read()
if "distress_base.json is THE distress rule" in r:
    print("  = genomes/README.md: note already present")
else:
    open("genomes/README.md", "a").write(ADD); print("  + genomes/README.md note")

print("\nDone. READ DISTRESS_PREREG.md before running anything -- Gate A first.")
